import {trainingView,shopView,labView as autoLabView,studioView,bindLearning,cleanupLearning} from './learning-ui.mjs';
import {evolutionView,bindEvolution} from './evolution-ui.mjs';
import {calculateChart,calculateTiming,deriveVariables,composite,chartSummary,SynthiaGuide,CENTER_THEMES,TYPE_GUIDANCE,AUTHORITY_GUIDANCE} from './deep-engine.mjs';
import {ActivationEngine} from './BiverseCore.mjs';
import {GATE_NAMES,LINE_NAMES} from './knowledge.mjs';
const KEY='synthia-workspace-v1';
let corpus={gates:[],sources:[]},view='overview',section='activations',search='',selectedCenter=null;
const defaults={profiles:[],active:null,chat:[],notes:[]};
let db;try{db={...defaults,...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{db=structuredClone(defaults);}
const guide=new SynthiaGuide({getItem:()=>'{"observations":[]}',setItem:()=>{}});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>String(s??'').replace(/[-_]/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const current=()=>db.profiles.find(p=>p.id===db.active)||null;
const chart=()=>current()?.chart;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('Device storage is full. Export your data before adding more.');}}
function toast(t){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),3500);}
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',assistant:'<path d="M21 11a8 8 0 0 1-8 8H4l-2 3V11a9 9 0 1 1 19 0Z"/><path d="M7 10h8m-8 4h5"/>',explore:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',gates:'<path d="M4 3h13v18H4zM7 7h7M7 11h7M7 15h4M17 5h3v16h-3"/>',notes:'<path d="M4 4h16v16H4zM8 8h8M8 12h8M8 16h4"/>',sources:'<path d="M3 7h7l2 2h9v12H3zM3 7V3h7l2 2h9v4"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.explore}</svg>`;
const NAV=[['overview','My workspace'],['assistant','Synthia assistant'],['explore','Chart explorer'],['gates','64 gate library'],['notes','Reflection lab'],['training','Local training'],['shop','Model Go Round Shoppe'],['autolab','Auto Lab'],['studio','Publishing Studio'],['evolution','Build & evolve'],['sources','Sources & models']];
const prompts=['How can I make decisions with more clarity?','Explain my defined and open centers','What do my active gates mean?'];
const sourceId='1FtkpJLnar6PTYa4k0BABIbIffDNE02aB';
const sourceUrl=id=>corpus.sources.find(s=>s.id===id)?.url||`https://drive.google.com/file/d/${id}/view`;
function sourceLink(id,label){return `<a href="${esc(sourceUrl(id))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;}
function head(eyebrow,name,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${name}</h1><p class="head-description">${desc}</p></div>${action}</div>`;}
function shell(content){return `<div class="layout"><aside class="sidebar"><div class="brand"><img class="logo" src="favicon.svg" alt="">synthia</div><div class="brand-sub">HUMAN DESIGN</div><p class="nav-label">YOUR EXPLORATION</p><nav class="nav" aria-label="Main navigation">${NAV.map(([id,label])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(id)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>A space to understand yourself.</strong>Charts and reflections are saved on this device.<br><button data-action="data">Manage my data</button><br><span class="pill dark">Local interpretation mode</span></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Human Design &nbsp; / &nbsp; <b>${NAV.find(x=>x[0]===view)?.[1]}</b></div><div class="top-actions"><span class="pill">Private on this device</span>${db.profiles.length?`<select id="profile" aria-label="Select chart">${db.profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===db.active?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:''}<div class="avatar">${esc(current()?.name?.slice(0,2).toUpperCase()||'SY')}</div></div></header><main class="content">${content}<footer class="method"><strong>About the method.</strong> Human Design is an interpretive framework for reflection. Charts use your supplied Synthia engine’s approximate orbital calculations. Verify chart boundaries and fine subdivisions with a high-precision ephemeris before professional use. Synthia currently uses local interpretation rules and source retrieval; a hosted language model is not connected.</footer></main></div></div><dialog id="dialog"></dialog>`;}
const CENTERS={Head:[220,40,'triangle'],Ajna:[220,114,'down'],Throat:[220,195,'square'],G:[220,290,'diamond'],Heart:[316,282,'triangle'],Spleen:[80,348,'triangle'],'Solar Plexus':[365,348,'triangle'],Sacral:[220,390,'square'],Root:[220,474,'square']};
const CHANNELS=new ActivationEngine().evaluate(Array.from({length:64},(_,i)=>i+1)).channels;
function bodygraph(c){const lines=CHANNELS.map(ch=>{const [a,b]=ch.centers.map(n=>CENTERS[n]);const active=ch.gates.every(g=>c?.activeGates.includes(g));const p=ch.gates.every(g=>c?.personalityGates.includes(g));const d=ch.gates.every(g=>c?.designGates.includes(g));return `<path d="M${a[0]} ${a[1]} L${b[0]} ${b[1]}" stroke="${active?(p?'#17282f':d?'#f09675':'#829d53'):'#dce4e2'}" stroke-width="${active?5:2}" opacity="${active?1:.65}"><title>${ch.code} ${esc(ch.name)} · ${active?'Defined':'Incomplete'}</title></path>`;}).join('');return `<svg class="chart-svg" viewBox="0 0 440 530" role="img" aria-label="Schematic bodygraph with nine centers; select a center for its meaning"><g>${lines}</g>${Object.entries(CENTERS).map(([name,[x,y,shape]])=>{const defined=c?.centers.includes(name);const poly=shape==='triangle'?`${x},${y-32} ${x-35},${y+24} ${x+35},${y+24}`:shape==='down'?`${x-35},${y-24} ${x+35},${y-24} ${x},${y+32}`:`${x},${y-34} ${x+34},${y} ${x},${y+34} ${x-34},${y}`;return `<g class="center-btn" tabindex="0" role="button" data-center="${name}" aria-label="${name}, ${defined?'defined':'open'}">${shape==='square'?`<rect class="center-shape ${defined?'defined':''}" x="${x-30}" y="${y-27}" width="60" height="54" rx="3"/>`:`<polygon class="center-shape ${defined?'defined':''}" points="${poly}"/>`}<text class="center-label" text-anchor="middle" x="${x}" y="${y+4}">${name==='Solar Plexus'?'Solar':name}</text><title>${name} · ${defined?'Defined':'Open / undefined'}</title></g>`;}).join('')}</svg>`;}
function metric(label,value){return `<div class="metric"><small>${label}</small><b>${esc(title(value))}</b></div>`;}
function assistantPrompt(){return `<div class="input-wrap"><textarea id="question" aria-label="Ask Synthia" placeholder="Ask about your design…" rows="1"></textarea><button class="button lime" data-action="ask">Ask</button></div>`;}
function overview(){const c=chart(),p=current();return head('YOUR PERSONAL WORKSPACE',p?`${esc(p.name)}’s design`:'Begin with your design',p?'Explore the mechanics. Notice what resonates. Test it in everyday life.':'Create your chart, explore your gates, and ask better questions.',`<button class="button secondary" data-action="create">${icon('plus')}${p?'Add a chart':'Create my chart'}</button>`)+(c?`<div class="metrics">${metric('ENERGY TYPE',c.type)}${metric('INNER AUTHORITY',c.authority)}${metric('PROFILE',c.profile)}${metric('DEFINITION',c.definition)}</div>`:'')+`<div class="grid"><section class="card chart-card"><div class="card-title"><h2>Your bodygraph</h2><span class="pill">${c?'Approximate chart':'No chart yet'}</span></div>${bodygraph(c)}${c?`<div class="legend"><span><i></i>Defined center</span><span><i class="open"></i>Open / undefined</span></div><div class="center-detail">${selectedCenter?centerText(selectedCenter,c):'Select a center to explore its role. Colored connections show complete channels.'}</div>`:`<div class="empty-chart"><h3>Your map starts with a moment.</h3><p class="muted small">Enter your birth details to reveal your chart.<br>This diagram is uncalculated.</p><button class="button" data-action="create">Create my chart</button></div>`}</section><section class="card assistant-card"><div class="card-title"><div class="assistant-heading"><div class="assistant-mark">✧</div><div><h2>Meet Synthia</h2><span class="muted small">Your qualitative guide</span></div></div><span class="pill dark">LOCAL</span></div><p class="assistant-intro">A conversation with<br>your own design.</p><p class="muted">Explore the why behind your chart, connect it to real experiences, and keep the sources in view.</p><div class="prompt-list">${prompts.map(q=>`<button class="prompt" data-prompt="${esc(q)}">${esc(q)}</button>`).join('')}</div>${assistantPrompt()}<p class="helper">Source-linked reflection. Your judgment stays at the center.</p></section></div><div class="bottom-grid"><section class="card"><div class="card-title"><div class="eyebrow">${c?'YOUR FIRST EXPERIMENT':'A PRACTICAL START'}</div><span class="pill">Reflection</span></div><h2>${c?title(c.strategy):'Notice before you interpret.'}</h2><p class="muted">${c?esc(AUTHORITY_GUIDANCE[c.authority]||chartSummary(c)):'Choose a small decision. Write down the situation, what you felt, and what happened. Your observations give the conversation context.'}</p><button class="link-button" data-nav="notes">Open reflection lab</button></section><section class="card"><div class="card-title"><div class="eyebrow">YOUR KNOWLEDGE FOUNDATION</div><span class="pill">22 linked files</span></div><h2>Trace every interpretation.</h2><p class="muted">A 64-gate reference library and selected readable notes from your supplied packages. Model Maker source is inspected; its model-training Space is linked. Coding inference still needs configuration.</p><button class="link-button" data-nav="sources">Explore sources & models</button></section></div>`;}
function centerText(n,c){const [theme,pressure]=CENTER_THEMES[n];return `<strong>${n} · ${c?.centers.includes(n)?'Defined':'Open / undefined'}</strong><br>Theme: ${esc(theme)}. Reflection prompt: where do you notice ${esc(pressure)}?`}
function answer(q){const c=chart(),refs=[],parts=[];const matches=q.match(/(?:gate|闸门)\s*(\d{1,2})\b/ig)||[];const gateNums=[...new Set(matches.map(x=>Number(x.match(/\d+/)[0])).filter(n=>n>=1&&n<=64))];const ctx=c?{chart:c,variables:deriveVariables(c),timing:calculateTiming(c),relationship:db.profiles.length>1?composite(c,db.profiles.find(p=>p.id!==db.active).chart):null}:null;
 if(c){guide.memory.observations=db.notes.filter(n=>n.profile===db.active);const base=guide.answer(q,ctx);if(!gateNums.length){parts.push(base.text);refs.push({id:sourceId,label:'Synthia · interpretation rules'});}}
 if(gateNums.length){gateNums.forEach(n=>{const g=corpus.gates.find(g=>g.gate===n);if(!g)return;const acts=c?.geonatal.placements.filter(p=>p.frame==='tropical'&&p.gate===n)||[];parts.push(`GATE ${n} · ${g.name}\n${g.center} center · ${g.circuit} circuit · Channel partners: ${g.channels.join(', ')}.\n${c?(acts.length?`Your approximate chart activates this gate through ${acts.map(p=>`${p.planetary} (${p.orientation}, line ${p.line})`).join('; ')}.`:'This gate is not active in the selected approximate chart.'):'Create a chart to see whether this gate is active for you.'}\n\nOriginal reference excerpt (Chinese):\n${g.text.split('##')[1]?.replace(/^\s*核心主题\s*/,'').trim()||g.text.slice(0,550)}`);});refs.push({id:'19IoK5KZ-Ds9JqbP85lpCFwMlxVlvXcNh',label:'Biverse corrected · gate references'},{id:'1AA3_4zLzCpz8jff3SpboB1hq0Z3mzOIJ',label:'Supplied gate data · mechanics'});}
 if(!c&&!gateNums.length){if(/decision|clarity|authority/i.test(q)){parts.push('Start with the actual choice in front of you. What are your options, what do you feel, and when must you decide? Human Design distinguishes strategy from inner authority. A chart can provide an interpretive lens, while your circumstances and observations supply the context.\n\nCreate a chart to explore your calculated authority, or ask about a specific gate—for example, “Explain gate 14”.');refs.push({id:sourceId,label:'Synthia · authority guidance'});}else if(/center/i.test(q)){parts.push('In the supplied engine, a center is defined when a complete channel connects its gates. A single activated gate does not define a center. Open or undefined centers are useful reflection topics, rather than proof of a missing ability.\n\nCreate a chart to explore your nine centers, or select a center on the bodygraph.');refs.push({id:sourceId,label:'Synthia · chart mechanics'});}else{parts.push('I can explain specific gates and source material now. Create your chart for personal strategy, authority, centers, channels, and timing.\n\nTry “Explain gate 1”, “What is inner authority?”, or “Which sources are available?”');refs.push({id:sourceId,label:'Synthia · interpretation rules'});}}
 const words=q.toLowerCase().split(/[^a-z0-9]+/).filter(w=>w.length>4&&!['about','please','explain','their','would','could','which','should'].includes(w));if(/source|architecture|synthia|model|codon|movement|evolution|being|space|proximology/i.test(q)){const hits=corpus.sources.flatMap(s=>s.notes.map(n=>({s,n,score:words.reduce((a,w)=>a+(n.text.toLowerCase().includes(w)?1:0),0)}))).filter(h=>h.score>0).sort((a,b)=>b.score-a.score).slice(0,2);for(const h of hits){const paras=h.n.text.split(/\n\s*\n/).filter(p=>p.length>50&&p.length<1200&&!p.includes('```'));const passage=paras.find(p=>words.some(w=>p.toLowerCase().includes(w)))||paras[0];if(passage){parts.push(`FROM YOUR MATERIALS · ${h.s.title}\n${h.n.path}\n\n${passage}`);refs.push({id:h.s.id,label:h.s.title});}}}
 if(/model|hugging|github/i.test(q))parts.push('Your Model Maker repository has been inspected and its Hugging Face training Space is linked. Coding evolution still needs an inference-capable model and a server-side credential. Open Build & Evolve to prepare a reviewed change. This response comes from local rules and source retrieval.');
 parts.push(/career|job|work|relationship|partner|decision|choose|clarity/i.test(q)?'TRY IN REAL LIFE\nChoose one small, reversible experiment. Record the situation, the body signal you noticed, the action you took, and the result. Compare observations over time rather than treating one response as a verdict.':'REFLECTION\nWhat part matches your lived experience, and what part does not? Record a concrete example so future conversations have your observations to work with.');
 return {text:parts.join('\n\n'),refs:[...new Map(refs.map(r=>[r.id,r])).values()]};}
function ask(q){q=String(q||'').trim();if(!q)return;if(q.length>3000){toast('Please keep questions under 3,000 characters.');return;}const a=answer(q);db.chat.push({role:'user',text:q,profile:db.active},{role:'assistant',...a,profile:db.active});db.chat=db.chat.slice(-100);view='assistant';save();render();}
function assistant(){const c=chart();const messages=db.chat.filter(m=>m.profile===db.active);return head('SOURCE-LINKED CONVERSATION','Ask Synthia','Explore your chart through questions, context, and observation.')+`<div class="chat-grid"><section class="card"><div class="card-title"><div class="assistant-heading"><div class="assistant-mark">✧</div><div><h2>Synthia</h2><span class="muted small">Local rules + source retrieval</span></div></div>${messages.length?'<button class="link-button" data-action="clear-chat">Clear chat</button>':''}</div><div class="chat" id="chat" aria-live="polite">${messages.length?messages.map(m=>`<article class="message ${m.role}"><div class="message-label">${m.role==='user'?'YOU':'SYNTHIA · INTERPRETIVE'}</div>${esc(m.text)}${m.refs?.length?`<div class="evidence">${m.refs.map(r=>sourceLink(r.id,r.label)).join('')}</div>`:''}</article>`).join(''):`<div class="message"><div class="message-label">SYNTHIA</div>${c?'Your chart is selected. Tell me what you’re exploring, or start with one of the questions below.':'You can explore the source library now. Create a chart when you’re ready for personal interpretation.'}</div>`}</div><div class="tabs">${['Explain my chart','Explain gate 14','How should I make a decision?'].map(q=>`<button data-prompt="${q}">${q}</button>`).join('')}</div>${assistantPrompt()}<p class="muted small" style="margin:12px 0 0">Answers are generated locally from explicit rules and retrieved excerpts. No hosted LLM is connected.</p></section><aside class="card context-card"><div class="eyebrow">CONVERSATION CONTEXT</div><h2>${esc(current()?.name||'Your workspace')}</h2>${c?`<div class="context-line"><span class="muted">Type</span><b>${title(c.type)}</b></div><div class="context-line"><span class="muted">Authority</span><b>${title(c.authority)}</b></div><div class="context-line"><span class="muted">Profile</span><b>${c.profile}</b></div><div class="context-line"><span class="muted">Active gates</span><b>${c.activeGates.length}</b></div>`:'<p class="muted">A chart gives your conversation a personal starting point.</p><button class="button" data-action="create">Create a chart</button>'}<div class="context-line"><span class="muted">Your reflections</span><b>${db.notes.filter(n=>n.profile===db.active).length}</b></div><div class="stat-note"><b class="small">Evidence, then reflection.</b><p class="small" style="margin:8px 0 0">Chart facts, source excerpts, and interpretive suggestions remain visible in each answer.</p></div></aside></div>`;}
function explore(){const c=chart();if(!c)return head('CHART EXPLORER','Your chart, in detail.','Create a chart to explore your activations, variables, and timing.')+`<div class="empty"><p>No chart selected.</p><button class="button" data-action="create">Create a chart</button></div>`;let content='';if(section==='activations'){content=`<div class="card"><div class="card-title"><h2>Personality & Design</h2><button class="button secondary" data-action="export">${icon('download')}Export data</button></div><div class="table-wrap"><table><thead><tr><th>PLANET</th><th>SIDE</th><th>GATE & LINE</th><th>COLOR · TONE · BASE</th><th>LONGITUDE</th></tr></thead><tbody>${c.geonatal.placements.filter(p=>p.frame==='tropical').map(p=>`<tr><td>${p.planetary}</td><td>${title(p.orientation)}</td><td><button class="link-button" data-gate="${p.gate}">${p.gate}.${p.line} · ${GATE_NAMES[p.gate]}</button></td><td>${p.color} · ${p.tone} · ${p.base}</td><td>${p.longitude.toFixed(4)}°</td></tr>`).join('')}</tbody></table></div><p class="notice">Fine subdivisions are particularly sensitive to ephemeris precision. These values are exploratory.</p></div>`;}if(section==='variables'){const v=deriveVariables(c);content=`<div class="metrics">${v.items.map(i=>metric(i.role,`${i.orientation} · ${i.label}`)).join('')}</div><div class="bottom-grid"><div class="card"><div class="eyebrow">DETERMINATION</div><h2>${v.determination.variant} ${v.determination.name}</h2><p>Cognition: ${v.determination.cognition}</p><p class="muted">Observe sensory conditions gently. This is a reflection prompt, not a dietary prescription.</p></div><div class="card"><div class="eyebrow">ENVIRONMENT</div><h2>${v.environment.variant} ${v.environment.name}</h2><p>Sense: ${v.environment.sense}</p><p class="muted">Explore the quality of the setting rather than taking its label literally.</p></div><div class="card"><div class="eyebrow">MOTIVATION</div><h2>${v.mind.motivation}</h2><p class="muted">Transference: ${v.mind.transference}</p></div><div class="card"><div class="eyebrow">PERSPECTIVE</div><h2>${v.view.perspective}</h2><p class="muted">Distraction: ${v.view.distraction}</p></div></div>`;}if(section==='timing'){const t=calculateTiming(c);content=`<div class="card"><div class="card-title"><h2>Current transits</h2><span class="pill">${new Date().toLocaleDateString()}</span></div><p class="muted">A reflective lens on the current moment. Approximate positions, with a 3° aspect orb.</p><div class="table-wrap"><table><thead><tr><th>TRANSITING BODY</th><th>ASPECT</th><th>NATAL BODY</th><th>ORB</th></tr></thead><tbody>${t.aspects.map(a=>`<tr><td>${a.moving}</td><td>${title(a.name)}</td><td>${a.natal}</td><td>${a.orb.toFixed(2)}°</td></tr>`).join('')||'<tr><td colspan="4">No major aspects within the configured orb.</td></tr>'}</tbody></table></div></div>`;}if(section==='connection'){content=db.profiles.length<2?`<div class="empty"><p>Add a second chart to explore the connection field.</p><button class="button" data-action="create">Add another chart</button></div>`:`<div class="card"><h2>Connection field</h2><label for="partner">Compare ${esc(current().name)} with</label><select id="partner">${db.profiles.filter(p=>p.id!==db.active).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><div id="connection-result"></div><p class="notice">This compares channel mechanics and shared activations. It does not score the quality of a relationship.</p></div>`;}return head('CHART EXPLORER','Look beneath the surface.','Read your activations, then explore the layers around them.')+`<div class="tabs">${[['activations','Activations'],['variables','PHS & variables'],['timing','Current timing'],['connection','Connections']].map(([id,l])=>`<button data-section="${id}" class="${section===id?'active':''}">${l}</button>`).join('')}</div>${content}`;}
function gates(){const c=chart();const filtered=corpus.gates.filter(g=>`${g.gate} ${g.name} ${g.center} ${g.circuit}`.toLowerCase().includes(search.toLowerCase()));return head('REFERENCE LIBRARY','64 gates. Many ways to explore.','Gate mechanics from your supplied files, with original reference notes.')+`<label for="gate-search" class="small muted">Search by number, name, center, or circuit</label><input class="search" id="gate-search" value="${esc(search)}" placeholder="Try 14, The Creative, Sacral…"><div class="gate-grid" id="gate-grid">${filtered.map(g=>`<button class="gate ${c?.activeGates.includes(g.gate)?'active':''}" data-gate="${g.gate}"><span class="gate-number">${String(g.gate).padStart(2,'0')}</span>${c?.activeGates.includes(g.gate)?'<span class="pill">Active</span>':''}<h3>${esc(g.name)}</h3><span class="small muted">${esc(g.center)} · ${g.circuit}</span></button>`).join('')||'<p class="muted">No gates match your search.</p>'}</div>`;}
function notes(){return head('REFLECTION LAB','Let experience have a voice.','Record what you noticed. Revisit it with Synthia.')+`<div class="notes-grid"><section class="card"><h2>A small experiment</h2><form id="note-form"><div class="field"><label for="note">Situation & what you noticed</label><textarea id="note" required maxlength="4000" placeholder="What happened? What did you feel? What did you do?"></textarea></div><div class="field" style="margin-top:15px"><label for="followed">Did you follow your authority?</label><select id="followed"><option>Unsure</option><option>Yes</option><option>No</option></select></div><div class="form-grid" style="margin-top:15px"><div class="field"><label for="outcome">Outcome</label><select id="outcome"><option>Pending</option><option>Aligned</option><option>Successful</option><option>Mixed</option><option>Not aligned</option></select></div><div class="field"><label for="signal">Body signal</label><input id="signal" maxlength="150" placeholder="Ease, tension…"></div></div><button class="button" style="margin-top:20px" type="submit">Save reflection</button></form><p class="notice">${current()?`Saved with ${esc(current().name)}’s chart.`:'Saved as a general reflection.'} Stays on this device.</p></section><section>${db.notes.filter(n=>n.profile===db.active).slice().reverse().map(n=>`<article class="note"><div class="row spread"><span class="pill">${esc(n.outcome)}</span><span class="small">${new Date(n.at).toLocaleDateString()}</span></div><p>${esc(n.text)}</p><div class="row spread"><span class="small">Authority: ${esc(n.followed)} · ${esc(n.signal||'No body signal recorded')}</span><button class="delete-note" data-delete-note="${n.id}">Delete</button></div></article>`).join('')||'<div class="empty"><div class="welcome-icon">✧</div><h3>Your observations belong here.</h3><p>Start with one ordinary decision.<br>There is no perfect response to record.</p></div>'}</section></div>`;}
function sources(){return head('KNOWLEDGE & CONNECTIONS','Know where the answer begins.','Your supplied materials and the assistant’s current capabilities.')+`<div class="three-grid"><div class="card"><div class="eyebrow">INTERPRETATION</div><h2>Local Synthia</h2><span class="pill">Available</span><p class="muted" style="margin-top:15px">Chart rules, 64 gate records, and selected source excerpts. No remote model is used.</p></div><div class="card"><div class="eyebrow">YOUR REPOSITORY</div><h2>Model Maker</h2><span class="pill">Source inspected</span><p class="muted" style="margin-top:15px">The Gradio model builder is linked with an approval-controlled evolution workflow.</p><a href="https://github.com/justappgrabbin/Stellarproximology-lab" target="_blank" rel="noopener noreferrer">Open Model Maker source</a></div><div class="card"><div class="eyebrow">YOUR MODEL</div><h2>Hugging Face</h2><span class="pill">Training Space linked</span><p class="muted" style="margin-top:15px">Modelmaker trains specialized models. It is not yet a connected chat or coding inference endpoint.</p><a href="https://huggingface.co/spaces/stellarproximology/Modelmaker" target="_blank" rel="noopener noreferrer">Open Modelmaker</a></div></div><section class="card" style="margin-top:24px"><div class="card-title"><h2>22 supplied files</h2><span class="pill">Source inventory</span></div><p class="muted small">All files were downloaded. The searchable library includes the 64 gate references and selected README, architecture, and integration notes. Archives are not live services; an inventory entry does not mean all of its code is running.</p>${corpus.sources.map(s=>`<div class="source-row"><div class="source-icon">${s.title.endsWith('.docx')?'D':'Z'}</div><div><h3>${esc(s.title)}</h3><p>${s.readable?`${s.notes.length} selected readable notes · ${s.files} inspected text/code files`:'Metadata only · no selected readable notes'}${s.id===sourceId?' · Chart engine & interpretation rules':''}${s.id==='19IoK5KZ-Ds9JqbP85lpCFwMlxVlvXcNh'?' · 64 original gate references':''}</p></div><a class="button secondary" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open source</a></div>`).join('')}</section>`;}
function evolution(){return evolutionView(db.notes.length);}
function training(){return trainingView();}
function shop(){return shopView();}
function autolab(){return autoLabView();}
function studio(){return studioView();}
function render(){cleanupLearning();document.querySelector('#app').innerHTML=shell(({overview,assistant,explore,gates,notes,sources,evolution,training,shop,autolab,studio}[view]||overview)());bind();if(view==='assistant')requestAnimationFrame(()=>{const el=document.querySelector('#chat');el.scrollTop=el.scrollHeight;});}
function showDialog(html){const d=document.querySelector('#dialog');d.innerHTML=`<button class="xbutton" aria-label="Close dialog">×</button>${html}`;d.querySelector('.xbutton').onclick=()=>d.close();d.showModal();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});return d;}
function create(){const d=showDialog(`<div class="eyebrow">BIRTH DETAILS</div><h2>Create your chart</h2><form id="birth-form"><div class="form-grid"><div class="field wide"><label for="name">Name</label><input id="name" required maxlength="80" autocomplete="name"></div><div class="field"><label for="date">Birth date</label><input id="date" type="date" required min="1800-01-01" max="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label for="time">Birth time</label><input id="time" type="time" required></div><div class="field"><label for="offset">UTC offset at birth</label><input id="offset" required placeholder="+00:00" pattern="[+-][0-9]{2}:[0-9]{2}" title="For example +05:30 or -04:00"></div><div class="field"><label for="place">Birth place (optional label)</label><input id="place" maxlength="120" placeholder="City, country"></div><div class="field"><label for="lat">Latitude</label><input id="lat" type="number" step="any" min="-90" max="90" required placeholder="e.g. 51.5074"></div><div class="field"><label for="lon">Longitude</label><input id="lon" type="number" step="any" min="-180" max="180" required placeholder="e.g. -0.1278"></div></div><p class="notice">Use the historical UTC offset, including daylight saving if applicable. Place labels do not geocode automatically. Birth details are stored only on this device. Chart calculations are approximate.</p><div id="birth-error" class="error" role="alert"></div><button class="button" type="submit">Calculate chart</button></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();try{const val=id=>d.querySelector('#'+id).value;const offset=val('offset'),sign=offset[0]==='-'?-1:1,h=Number(offset.slice(1,3)),m=Number(offset.slice(4,6));if(h>14||m>59||(h===14&&m!==0))throw Error('Enter a UTC offset between -14:00 and +14:00.');const date=val('date'),time=val('time'),timestamp=new Date(`${date}T${time}:00Z`);timestamp.setUTCMinutes(timestamp.getUTCMinutes()-sign*(h*60+m));if(!Number.isFinite(timestamp.getTime())||timestamp>new Date())throw Error('Enter a valid past birth moment.');const latitude=Number(val('lat')),longitude=Number(val('lon'));if(Math.abs(latitude)>90||Math.abs(longitude)>180)throw Error('Coordinates are outside their valid range.');const p={id:crypto.randomUUID(),name:val('name').trim(),date,time,offset,latitude,longitude,place:val('place'),chart:calculateChart(timestamp,{latitude,longitude})};if(!p.name)throw Error('Enter a name.');db.profiles.push(p);db.active=p.id;selectedCenter=null;view='overview';save();d.close();render();toast('Your approximate chart is ready.');}catch(err){d.querySelector('#birth-error').textContent=err.message;}};}
function gateDetail(n){const g=corpus.gates.find(g=>g.gate===n);if(!g)return;const c=chart();const active=c?.activeGates.includes(n);const d=showDialog(`<div class="eyebrow">GATE ${String(n).padStart(2,'0')}</div><h2>${esc(g.name)}</h2><div class="row"><span class="pill">${g.center}</span><span class="pill">${g.circuit}</span>${c?`<span class="pill">${active?'Active in selected chart':'Not active in selected chart'}</span>`:''}</div><p class="muted" style="margin-top:20px">Channel partners: ${g.channels.join(', ')}. ${c?'Based on the approximate local chart.':''}</p><details><summary>Original reference notes (Chinese)</summary><div class="gate-text">${esc(g.text)}</div></details><div class="evidence">${sourceLink('19IoK5KZ-Ds9JqbP85lpCFwMlxVlvXcNh','Biverse corrected · original gate notes')}${sourceLink('1AA3_4zLzCpz8jff3SpboB1hq0Z3mzOIJ','Gate mechanics · supplied gateData.ts')}</div><button class="button" id="ask-gate" style="margin-top:24px">Ask Synthia about this gate</button>`);d.querySelector('#ask-gate').onclick=()=>{d.close();ask(`Explain gate ${n}`);};}
function exportData(){const blob=new Blob([JSON.stringify({format:'synthia-workspace-v1',exportedAt:new Date().toISOString(),...db},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='synthia-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function dataDialog(){const d=showDialog(`<div class="eyebrow">DEVICE STORAGE</div><h2>Your data is yours.</h2><p class="muted">${db.profiles.length} charts, ${db.notes.length} reflections, and ${db.chat.length} conversation messages are saved in this browser. They do not sync to other devices.</p><div class="row"><button class="button secondary" id="export-all">Export my data</button><button class="button danger" id="delete-all">Delete all local data</button></div><p class="notice">Export first if you want to keep a copy. Deleting clears all charts, conversations, and reflections from this device.</p><div id="delete-confirm"></div>`);d.querySelector('#export-all').onclick=exportData;d.querySelector('#delete-all').onclick=()=>{d.querySelector('#delete-confirm').innerHTML='<p>Delete all saved charts, chats, and reflections?</p><button class="button danger" id="confirm-delete">Yes, delete all</button>';d.querySelector('#confirm-delete').onclick=()=>{db=structuredClone(defaults);save();view='overview';d.close();render();toast('Local data deleted.');};};}
function connection(){const id=document.querySelector('#partner')?.value;const p=db.profiles.find(p=>p.id===id);if(!p)return;const r=composite(chart(),p.chart);document.querySelector('#connection-result').innerHTML=`<h3 style="margin-top:25px">Electromagnetic channel completions</h3>${r.electromagnetic.map(c=>`<span class="tag">${c.code} · ${c.name}</span>`).join('')||'<p class="muted">No completions in this pair.</p>'}<h3 style="margin-top:15px">Shared gates</h3>${r.gates.shared.map(g=>`<button class="tag" data-gate="${g}">${g} · ${GATE_NAMES[g]}</button>`).join('')||'<p class="muted">No shared gates.</p>'}`;document.querySelectorAll('#connection-result [data-gate]').forEach(el=>el.onclick=()=>gateDetail(Number(el.dataset.gate)));}
function bind(){bindEvolution();bindLearning(render);document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>{view=el.dataset.nav;render();window.scrollTo(0,0);});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.action;if(a==='create')create();if(a==='ask')ask(document.querySelector('#question').value);if(a==='export')exportData();if(a==='data')dataDialog();if(a==='clear-chat'){db.chat=db.chat.filter(m=>m.profile!==db.active);save();render();}});document.querySelectorAll('[data-prompt]').forEach(el=>el.onclick=()=>ask(el.dataset.prompt));document.querySelectorAll('[data-section]').forEach(el=>el.onclick=()=>{section=el.dataset.section;render();});document.querySelectorAll('[data-gate]').forEach(el=>el.onclick=()=>gateDetail(Number(el.dataset.gate)));document.querySelectorAll('[data-center]').forEach(el=>{const act=()=>{selectedCenter=el.dataset.center;const text=centerText(selectedCenter,chart());document.querySelector('.center-detail')?.remove();const div=document.createElement('div');div.className='center-detail';div.innerHTML=text;document.querySelector('.chart-card').append(div);};el.onclick=act;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act();}};});document.querySelector('#profile')?.addEventListener('change',e=>{db.active=e.target.value;selectedCenter=null;save();render();});document.querySelector('#question')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask(e.target.value);}});document.querySelector('#gate-search')?.addEventListener('input',e=>{search=e.target.value;const input=e.target,pos=input.selectionStart;render();const next=document.querySelector('#gate-search');next.focus();next.setSelectionRange(pos,pos);});document.querySelector('#note-form')?.addEventListener('submit',e=>{e.preventDefault();const text=document.querySelector('#note').value.trim();if(!text)return;db.notes.push({id:crypto.randomUUID(),profile:db.active,text,followed:document.querySelector('#followed').value,outcome:document.querySelector('#outcome').value,signal:document.querySelector('#signal').value,at:new Date().toISOString()});save();render();toast('Reflection saved on this device.');});document.querySelectorAll('[data-delete-note]').forEach(el=>el.onclick=()=>{db.notes=db.notes.filter(n=>n.id!==el.dataset.deleteNote);save();render();});if(section==='connection'&&view==='explore'){connection();document.querySelector('#partner')?.addEventListener('change',connection);}}
render();
try{const response=await fetch('./corpus.json');if(!response.ok)throw Error('Source library unavailable');corpus=await response.json();render();}catch{toast('The source library could not load. Refresh to try again.');}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});register({name:'read_selected_human_design_chart',description:'Read the selected approximate Human Design chart and its current UI context.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return chart()?{name:current().name,type:chart().type,authority:chart().authority,profile:chart().profile,activeGates:chart().activeGates,centers:chart().centers,accuracy:'approximate'}:{chart:null};}});register({name:'ask_synthia',description:'Add a question and local source-linked interpretation to the visible Synthia conversation; saves messages on this device.',inputSchema:{type:'object',properties:{question:{type:'string',minLength:1,maxLength:3000}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(typeof input?.question!=='string'||!input.question.trim()||input.question.length>3000)throw Error('A question of 1–3000 characters is required.');ask(input.question);return {answer:db.chat.at(-1).text,sources:db.chat.at(-1).refs};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
